from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    results = []

    if kind == "DAILY":
        current = start_date
        step = timedelta(days=interval)
        for _ in range(count):
            results.append(current.isoformat())
            current += step
        return results

    if kind == "WEEKLY":
        weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                    "FR": 4, "SA": 5, "SU": 6}
        selected = {weekdays[code] for code in parts[2].split(",")}
        week_start = start_date - timedelta(days=start_date.weekday())
        week_index = 0

        while len(results) < count:
            if week_index % interval == 0:
                for weekday in sorted(selected):
                    current = week_start + timedelta(days=7 * week_index + weekday)
                    if current >= start_date:
                        results.append(current.isoformat())
                        if len(results) == count:
                            break
            week_index += 1
        return results

    if kind == "MONTHLY":
        start_month = start_date.year * 12 + start_date.month - 1
        month_index = 0

        while len(results) < count:
            if month_index % interval == 0:
                year, month0 = divmod(start_month + month_index, 12)
                month = month0 + 1
                last_day = calendar.monthrange(year, month)[1]

                if len(parts) == 3:
                    day_spec = int(parts[2])
                    day = last_day if day_spec == -1 else day_spec
                    if day <= last_day:
                        current = date(year, month, day)
                        if current >= start_date:
                            results.append(current.isoformat())
                else:
                    n = int(parts[2])
                    weekday = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                               "FR": 4, "SA": 5, "SU": 6}[parts[3]]
                    matching_days = [
                        day for day in range(1, last_day + 1)
                        if date(year, month, day).weekday() == weekday
                    ]
                    if n == -1:
                        day = matching_days[-1]
                    elif n <= len(matching_days):
                        day = matching_days[n - 1]
                    else:
                        day = None
                    if day is not None:
                        current = date(year, month, day)
                        if current >= start_date:
                            results.append(current.isoformat())
            month_index += 1
        return results

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year_index = 0
        while len(results) < count:
            year = start_date.year + year_index
            if year_index % interval == 0:
                try:
                    current = date(year, month, day)
                except ValueError:
                    current = None
                if current is not None and current >= start_date:
                    results.append(current.isoformat())
            year_index += 1
        return results
